-- Read-only native251 source/authority checks.
BEGIN READ ONLY;SET LOCAL ROLE celebix_saas_owner;
DO $functions$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission251_balance_projection(uuid,uuid)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='d76d2b89cf861f8a5f8286654e2689dcbb655f8305b0cb812cf8ff170dd520d7'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='s'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission251_balance_projection(uuid,uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission251_intent_valid(text,jsonb)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='dd280f36414b190140a8edf03383cd4dbe97c6d60c08f41530ff040dc3c6d1db'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS false AND p.provolatile='i'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission251_intent_valid(text,jsonb)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission251_payment_projection(uuid,uuid)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='d3205cdce072df9f1b7fb5d4672942be665852ac3724706890b41e919f6516cb'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='s'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission251_payment_projection(uuid,uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission_balances_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='cc40f1f16f59c4e9a4f09982b1aaae8ba77ac56c6368920867a755151290c636'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='s'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission_balances_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission_payment_mutate(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,text,uuid,text,jsonb)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='02c40e0b476a567f1b1ca9433ea99446ab0e603114e4187190e53052e8641a9c'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='v'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission_payment_mutate(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,text,uuid,text,jsonb)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission_payment_operation(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='add483b4e3b2efbd31559f8ebebb45de79446c8b69275f886fef7df8d207c22e'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='s'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission_payment_operation(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commission_payments_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid)')AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='dbe179bdb152af38a96388078a0fd8adfc7476e234fba75c4e6d2b79c896bebb'AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[]AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[]AND p.prosecdef IS true AND p.provolatile='s'AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_DRIFT:%','saas.accounting_commission_payments_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid)';END IF;
END $functions$;
DO $schema$DECLARE t text;BEGIN
 IF(SELECT count(*)FROM pg_proc WHERE pronamespace='saas'::regnamespace AND prokind='f')<>1895 THEN RAISE EXCEPTION 'COMMISSION251_FUNCTION_SCOPE';END IF;
 FOREACH t IN ARRAY ARRAY['accounting_commission_payments','accounting_commission_payment_operations']LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass('saas.'||t)AND c.relowner='celebix_saas_owner'::regrole AND c.relrowsecurity AND c.relforcerowsecurity)OR has_table_privilege('celebix_saas_app','saas.'||t,'SELECT,INSERT,UPDATE,DELETE')OR EXISTS(SELECT 1 FROM pg_class c,aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE c.oid=to_regclass('saas.'||t)AND a.grantee=0)THEN RAISE EXCEPTION 'COMMISSION251_PRIVATE_TABLE:%',t;END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=to_regclass('saas.'||t)AND polname='commission251_owner'AND polroles=ARRAY['celebix_saas_owner'::regrole::oid]AND polcmd='*'AND polpermissive AND pg_get_expr(polqual,polrelid)='true'AND pg_get_expr(polwithcheck,polrelid)='true')THEN RAISE EXCEPTION 'COMMISSION251_OWNER_POLICY:%',t;END IF;
  IF(SELECT count(*)FROM pg_trigger WHERE tgrelid=to_regclass('saas.'||t)AND NOT tgisinternal AND tgenabled='O'AND((tgname='accounting_immutable'AND tgfoid='saas.accounting_immutable()'::regprocedure)OR(tgname='platform_support_journal_write'AND tgfoid='saas.platform_support_journal_write()'::regprocedure)))<>2 THEN RAISE EXCEPTION 'COMMISSION251_IMMUTABILITY:%',t;END IF;
 END LOOP;
 IF(SELECT count(*)FROM pg_attribute WHERE attrelid='saas.accounting_commission_payments'::regclass AND attnum>0 AND NOT attisdropped)<>7 OR(SELECT count(*)FROM pg_attribute WHERE attrelid='saas.accounting_commission_payment_operations'::regclass AND attnum>0 AND NOT attisdropped)<>7 THEN RAISE EXCEPTION 'COMMISSION251_COLUMN_SCOPE';END IF;
 IF(SELECT count(*)FROM pg_constraint WHERE conrelid='saas.accounting_commission_payments'::regclass AND contype='f')<>3 OR(SELECT count(*)FROM pg_constraint WHERE conrelid='saas.accounting_commission_payment_operations'::regclass AND contype='f')<>2 THEN RAISE EXCEPTION 'COMMISSION251_FK_SCOPE';END IF;
 IF to_regclass('saas.accounting_commission251_member')IS NULL OR to_regclass('saas.accounting_commission251_entitlement')IS NULL THEN RAISE EXCEPTION 'COMMISSION251_INDEX_SCOPE';END IF;
 IF saas.built_in_payment_methods_preflight()IS DISTINCT FROM true OR saas.payment_provider_keyed_lifecycle_preflight()IS DISTINCT FROM true OR saas.iyzico_iframe_tenant_activation_runtime_preflight()IS DISTINCT FROM true OR saas.quick_order_hosted_payment_authority_preflight()IS DISTINCT FROM true OR saas.shipping_provider_preflight()IS DISTINCT FROM true THEN RAISE EXCEPTION 'COMMISSION251_PAYMENT_PREFLIGHT';END IF;
END $schema$;
ROLLBACK;
